import React, { useEffect, useState } from 'react';
import { fetchApplicant } from './api/apiClient';

const ApplicantDashboard = ({ applicantId }) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      setError('');
      try {
        const res = await fetchApplicant(applicantId);
        setData(res.data);
      } catch (err) {
        setError('Failed to load applicant data.');
      } finally {
        setLoading(false);
      }
    };
    if (applicantId) load();
  }, [applicantId]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div style={{color:'red'}}>{error}</div>;
  if (!data) return null;

  // Helper to pretty print resume structured data
  const resume = data.resume && data.resume.structured_data;
  const linkedin = data.linkedin;
  const insights = data.insights;

  return (
    <div>
      <h2>Applicant Dashboard</h2>
      <div><b>Name:</b> {data.name}</div>
      <div><b>Email:</b> {data.email}</div>
      <div><b>LinkedIn:</b> <a href={data.linkedin_url} target="_blank" rel="noopener noreferrer">{data.linkedin_url}</a></div>
      <div><b>Resume:</b>
        {resume ? (
          <ul style={{marginTop:4}}>
            {resume.name && <li><b>Name:</b> {resume.name}</li>}
            {resume.email && <li><b>Email:</b> {resume.email}</li>}
            {resume.phone && <li><b>Phone:</b> {resume.phone}</li>}
            {resume.skills && resume.skills.length > 0 && <li><b>Skills:</b> {resume.skills.join(', ')}</li>}
            {resume.raw_text && <li><b>Raw Text:</b> <pre style={{whiteSpace:'pre-wrap',fontSize:12}}>{resume.raw_text}</pre></li>}
          </ul>
        ) : 'Processing...'}
      </div>
      <div><b>LinkedIn Data:</b>
        {linkedin ? (
          linkedin.error ? (
            <span style={{color:'red'}}>Error fetching LinkedIn: {linkedin.error}</span>
          ) : (
            <pre style={{whiteSpace:'pre-wrap',fontSize:12}}>{JSON.stringify(linkedin, null, 2)}</pre>
          )
        ) : 'Processing...'}
      </div>
      <div><b>Insights:</b>
        {insights ? (
          <ul style={{marginTop:4}}>
            {insights.rating !== undefined && <li><b>Rating:</b> {insights.rating}</li>}
            {insights.summary && <li><b>Summary:</b> {insights.summary}</li>}
          </ul>
        ) : 'Processing...'}
      </div>
    </div>
  );
};

export default ApplicantDashboard;
